package com.google.gson.stream;

import com.google.gson.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(JUnit4.class)
public class JsonWriter_value_TriageGen2Test {

    private JsonWriter jsonWriter;

    @Before
    public void setup() {
        jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(true);
        jsonWriter.setHtmlSafe(true);
        jsonWriter.setSerializeNulls(true);
    }

    @Test
    public void testValueNull() throws IOException {
        jsonWriter.value(null);
        assertNull(jsonWriter.getDeferredName());
        assertEquals("", jsonWriter.toString());
    }

    @Test
    public void testValueString() throws IOException {
        jsonWriter.value("test");
        verify(jsonWriter, times(1)).writeDeferredName();
        verify(jsonWriter, times(1)).beforeValue(false);
        verify(jsonWriter, times(1)).string("test");
        assertEquals("{\n  \"test\"\n}", jsonWriter.toString());
    }

    @Test
    public void testValueBoolean() throws IOException {
        jsonWriter.value(true);
        verify(jsonWriter, times(1)).writeDeferredName();
        verify(jsonWriter, times(1)).beforeValue(false);
        verify(jsonWriter, times(1)).string("true");
        assertEquals("{\n  \"true\"\n}", jsonWriter.toString());
    }

    @Test
    public void testValueLong() throws IOException {
        jsonWriter.value(123L);
        verify(jsonWriter, times(1)).writeDeferredName();
        verify(jsonWriter, times(1)).beforeValue(false);
        verify(jsonWriter, times(1)).string("123");
        assertEquals("{\n  \"123\"\n}", jsonWriter.toString());
    }

    @Test
    public void testValueDouble() throws IOException {
        jsonWriter.value(123.45);
        verify(jsonWriter, times(1)).writeDeferredName();
        verify(jsonWriter, times(1)).beforeValue(false);
        verify(jsonWriter, times(1)).string("123.45");
        assertEquals("{\n  \"123.45\"\n}", jsonWriter.toString());
    }

    @Test
    public void testValueNumber() throws IOException {
        jsonWriter.value(123.45);
        verify(jsonWriter, times(1)).writeDeferredName();
        verify(jsonWriter, times(1)).beforeValue(false);
        verify(jsonWriter, times(1)).string("123.45");
        assertEquals("{\n  \"123.45\"\n}", jsonWriter.toString());
    }

    @Test
    public void testValueDeferredName() throws IOException {
        jsonWriter.writeDeferredName();
        jsonWriter.value("test");
        verify(jsonWriter, times(1)).writeDeferredName();
        verify(jsonWriter, times(1)).beforeValue(false);
        verify(jsonWriter, times(1)).string("test");
        assertEquals("{\n  \"test\"\n}", jsonWriter.toString());
    }

    @Test
    public void testValueDeferredNameMultipleTimes() throws IOException {
        jsonWriter.writeDeferredName();
        jsonWriter.value("test1");
        jsonWriter.writeDeferredName();
        jsonWriter.value("test2");
        verify(jsonWriter, times(2)).writeDeferredName();
        verify(jsonWriter, times(2)).beforeValue(false);
        verify(jsonWriter, times(2)).string("test1");
        verify(jsonWriter, times(2)).string("test2");
        assertEquals("{\n  \"test1\"\n  \"test2\"\n}", jsonWriter.toString());
    }
}
